'use strict';
/* V15 Improvement Batch 1. Self-contained game UIs; uses V15-only state. */
// Embedded offline images: no external SVG fetch or GitHub asset path required.
const GAME_INLINE_PICTURES={"apple":"","banana":"","bird":"","butterfly":"","carrot":"","cat":"","cherry":"","dog":"","duck":"","elephant":"","fish":"","flower":"","grapes":"","lemon":"","lion":"","orange":"","pear":"","rabbit":"","star":"","tiger":""};
/* Batch 2: bundled premium-looking AI-rendered object portraits; works offline without asset paths. */
const GAME_PREMIUM_3D={"lion":"","cat":"","dog":"","duck":"","apple":"","tiger":""};
const GAME_PREMIUM_NAMES=Object.keys(GAME_PREMIUM_3D);

const GAME_VOCAB=['APPLE','BANANA','ORANGE','PEAR','LEMON','GRAPES','CARROT','CHERRY','FISH','BIRD','CAT','DOG','LION','TIGER','RABBIT','DUCK','BUTTERFLY','ELEPHANT','FLOWER','STAR'];
const GAME_PICTURES={APPLE:'apple',BANANA:'banana',ORANGE:'orange',PEAR:'pear',LEMON:'lemon',GRAPES:'grapes',CARROT:'carrot',CHERRY:'cherry',FISH:'fish',BIRD:'bird',CAT:'cat',DOG:'dog',LION:'lion',TIGER:'tiger',RABBIT:'rabbit',DUCK:'duck',BUTTERFLY:'butterfly',ELEPHANT:'elephant',FLOWER:'flower',STAR:'star'};
const SAFARI_ANIMALS=['Lion','Tiger','Cat','Dog','Duck']; // Curated 3D illustrations only (Batch 2)
const SHAPE_TYPES=['Circle','Square','Triangle','Star','Heart'];
const RIZQI_PROGRESS='raesya-wonderland-v15-rizqi-progress-v2';
let gamePointer=null,gameTileBuffer=[],gameLastWords=[],gameLastPictures=[],shapeDrag=null;
function gamePick(list,recent){let candidates=list.filter(x=>!recent.includes(x));if(!candidates.length){recent.length=0;candidates=list.slice()}const result=candidates[Math.floor(Math.random()*candidates.length)];recent.push(result);if(recent.length>Math.min(12,list.length-1))recent.shift();return result}
function gameImage(id,alt,cssClass=''){if(GAME_PREMIUM_3D[id])return `<img class="premium-3d-picture ${cssClass}" src="data:image/webp;base64,${GAME_PREMIUM_3D[id]}" alt="${qSafe(alt)}" loading="eager" decoding="sync" draggable="false">`;const svg=GAME_INLINE_PICTURES[id];if(!svg)return `<span class="visual-error" role="img" aria-label="Picture missing">Picture unavailable: ${qSafe(alt)}</span>`;return `<img class="${cssClass}" src="data:image/svg+xml;base64,${svg}" alt="${qSafe(alt)}" loading="eager" decoding="sync" draggable="false" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="visual-error" hidden>Picture unavailable: ${qSafe(alt)}</span>`}
function shapeSvg(name){
 const cols={Circle:['#ff8f9d','#ff355e','#a92755'],Square:['#8fdcff','#2a9ae2','#1160a4'],Triangle:['#ffe87f','#ffad20','#cc7516'],Star:['#e0baff','#9756e5','#6433ac'],Heart:['#ffb9da','#ef64aa','#b73a7f']};
 const path={Circle:'<circle cx="60" cy="60" r="38"/>',Square:'<rect x="23" y="23" width="74" height="74" rx="13"/>',Triangle:'<path d="M60 15 L106 102 H14 Z"/>',Star:'<path d="M60 9 L74 43 L111 46 L82 70 L92 108 L60 87 L28 108 L38 70 L9 46 L46 43 Z"/>',Heart:'<path d="M60 104 C35 84 13 65 15 42 C17 16 47 10 60 35 C74 10 103 16 105 42 C107 65 85 84 60 104 Z"/>'}[name];
 const c=cols[name]||cols.Circle,tag='b2-'+name.toLowerCase();
 return `<svg class="shape-svg shape-toy" viewBox="0 0 120 120" aria-hidden="true"><defs><linearGradient id="${tag}-body" x1="0.1" y1="0" x2="0.85" y2="1"><stop stop-color="${c[0]}"/><stop offset=".57" stop-color="${c[1]}"/><stop offset="1" stop-color="${c[2]}"/></linearGradient><linearGradient id="${tag}-gloss" x1="0" x2=".6" y1="0" y2="1"><stop stop-color="white" stop-opacity=".7"/><stop offset="1" stop-color="white" stop-opacity="0"/></linearGradient><filter id="${tag}-shadow" x="-30%" width="160%" y="-30%" height="170%"><feDropShadow dx="1" dy="6" stdDeviation="3" flood-color="#3c3b62" flood-opacity=".32"/></filter></defs><g filter="url(#${tag}-shadow)"><g fill="url(#${tag}-body)" stroke="${c[2]}" stroke-width="3.5" stroke-linejoin="round">${path}</g><g fill="url(#${tag}-gloss)" transform="translate(-4,-6) scale(.89)">${path}</g></g></svg>`;
}

function gameNewWord(kind){const word=gamePick(kind==='spelling'?['APPLE','LION','TIGER','CAT','DOG','DUCK']:GAME_VOCAB,kind==='spelling'?gameLastPictures:gameLastWords);let letters=shuffled(word.split(''));if(letters.join('')===word){letters.push(letters.shift())}return {kind,word,picture:GAME_PICTURES[word],letters,score:0}}
function gameNewSearch(){const size=7;const pool=['CAT','DOG','STAR','TREE','BIRD','FISH','APPLE','MOON','RAIN','SUN','BOOK','LION','DUCK','PEAR'];const word=gamePick(pool,gameLastWords);const grid=Array.from({length:size},()=>Array.from({length:size},()=>String.fromCharCode(65+Math.floor(Math.random()*26))));const dirs=[[0,1],[1,0],[1,1],[0,-1],[1,-1]];let placements=[];for(const [dx,dy] of shuffled(dirs)){for(let row=0;row<size;row++)for(let col=0;col<size;col++){let endR=row+dy*(word.length-1),endC=col+dx*(word.length-1);if(endR>=0&&endR<size&&endC>=0&&endC<size)placements.push({row,col,dx,dy})}}const p=placements[Math.floor(Math.random()*placements.length)];const path=[];word.split('').forEach((letter,i)=>{let r=p.row+p.dy*i,c=p.col+p.dx*i;grid[r][c]=letter;path.push(r*size+c)});return {kind:'search',word,grid,size,path,selection:[],score:0}}
const oldFullNewGame=fullNewGame;
fullNewGame=function(kind){if(kind==='word'||kind==='spelling')return gameNewWord(kind);if(kind==='search')return gameNewSearch();if(kind==='math'){let g=oldFullNewGame(kind);g.right=Math.max(0,g.right);if(g.op==='−'&&g.a<g.b){let x=g.a;g.a=g.b;g.b=x;g.right=g.a-g.b}return g}return oldFullNewGame(kind)};
function gameWordBoard(g){let slots=g.word.split('').map((_,i)=>`<span class="letter-slot">${gameTileBuffer[i]?.letter||'·'}</span>`).join('');return `<div class="game-word-card"><div class="game-caption">BUILD THE WORD</div><div class="game-letter-slots" aria-label="Word in progress">${slots}</div><div class="game-letter-tray">${g.letters.map((x,i)=>`<button type="button" class="game-letter-tile" data-game-letter="${i}" ${gameTileBuffer.some(x=>x&&x.i===i)?'disabled':''} aria-label="Letter ${x}">${x}</button>`).join('')}</div><button class="action" data-game-reset>Clear letters</button></div>`}
function gameDraw(m){let kind=state.detail;if(!fullGame||fullGame.kind!==kind){fullGame=fullNewGame(kind);gameTileBuffer=[]}const g=fullGame;let body='';
 if(kind==='word')body=`<div class="game-hero word-theme"><span class="game-kicker">WORD PUZZLE · Score ${g.score}</span><h2>Arrange the letters!</h2><p>Tap each colourful letter to make an English word.</p></div>${gameWordBoard(g)}<p id="gameFeedback" role="status" class="game-feedback"></p><button class="action" data-game-new>Next word</button>`;
 else if(kind==='spelling')body=`<div class="game-hero spelling-theme"><span class="game-kicker">PICTURE SPELLING · Score ${g.score}</span><h2>Look, think & spell!</h2><p>What can you see in this picture?</p></div><div class="game-picture-frame">${gameImage(g.picture,'Object to spell')}</div><div class="game-spell-slots">${g.word.split('').map(()=>'<span>_</span>').join('')}</div><label class="game-input-label" for="gameWord">Type the English word</label><input id="gameWord" autocapitalize="characters" autocomplete="off" spellcheck="false" placeholder="Type your answer here"><div class="game-actions"><button class="action primary" data-improve-check>Check answer</button><button class="action" data-improve-hint>First-letter hint</button></div><p id="gameFeedback" role="status" class="game-feedback"></p>`;
 else if(kind==='math')body=`<div class="game-hero math-theme"><span class="game-kicker">MATH CHALLENGE · Score ${g.score}</span><h2>Little Maths Genius!</h2><p>Solve the problem inside the magic card.</p></div><div class="game-math-card"><div class="math-stars">✦  ✦  ✦</div><div class="math-operation" aria-label="${g.a} ${g.op} ${g.b} equals what">${g.a} <span>${g.op}</span> ${g.b} <span>=</span> <b>?</b></div><div class="math-stars">✦  ✦  ✦</div></div><label class="game-input-label" for="gameMath">Your answer</label><input id="gameMath" inputmode="numeric" type="number" placeholder="Enter a number"><button class="action primary" data-improve-check>Check answer</button><p id="gameFeedback" role="status" class="game-feedback"></p>`;
 else if(kind==='search')body=`<div class="game-hero search-theme"><span class="game-kicker">WORD SEARCH · Score ${g.score}</span><h2>Find the hidden word!</h2><p>Drag your finger or mouse across the letters, from the first to the last.</p></div><div class="search-target">FIND: <strong>${g.word}</strong></div><div class="game-search-board" style="--word-size:${g.size}" role="grid" aria-label="Word search: find ${g.word}">${g.grid.flat().map((l,i)=>`<div class="game-search-cell" role="gridcell" data-search-cell="${i}">${l}</div>`).join('')}</div><p class="game-search-tip">Touch and drag in a straight line • horizontal, vertical or diagonal</p><p id="gameFeedback" role="status" class="game-feedback"></p><button class="action" data-game-new>New word</button>`;
 return `<section class="panel app-screen module-shell improved-module">${head(m)}<div class="game-viewport">${body}</div></section>`}
fullGamesView=gameDraw;
function improveFeedback(msg,good=false){let f=document.getElementById('gameFeedback');if(f){f.textContent=msg;f.classList.toggle('is-good',good)}}
function gameSolved(){improveFeedback('Amazing! You found it! ⭐',true);improvePraise();let kind=fullGame.kind,score=fullGame.score+1;setTimeout(()=>{if(state.view==='games'&&state.detail===kind){fullGame=fullNewGame(kind);fullGame.score=score;gameTileBuffer=[];render()}},900)}
function gameSpellingCheck(){const g=fullGame;let input=document.getElementById('gameWord');let typed=(input?.value||'').trim().toUpperCase();if(typed===g.word)gameSolved();else improveFeedback('Try again! Look closely at the picture.')} 
function gameMathCheck(){const g=fullGame;let v=document.getElementById('gameMath')?.value;if(v!==''&&Number(v)===g.right)gameSolved();else improveFeedback('Almost! Try another answer.')} 
function gridLine(a,b,size){let ar=Math.floor(a/size),ac=a%size,br=Math.floor(b/size),bc=b%size,dr=br-ar,dc=bc-ac,steps=Math.max(Math.abs(dr),Math.abs(dc));if(steps===0)return [a];if(dr!==0&&dc!==0&&Math.abs(dr)!==Math.abs(dc))return [];return Array.from({length:steps+1},(_,i)=>(ar+Math.round(i*dr/steps))*size+ac+Math.round(i*dc/steps))}
function gridPaint(path){document.querySelectorAll('[data-search-cell]').forEach(el=>{el.classList.toggle('is-selected',path.includes(Number(el.dataset.searchCell)))})}
function gridFinish(path){let g=fullGame;if(!g||g.kind!=='search')return;let forward=path.join(',')===g.path.join(','),reverse=path.join(',')===g.path.slice().reverse().join(',');if(forward||reverse)gameSolved();else {improveFeedback('Keep searching. Drag along the word!');setTimeout(()=>gridPaint([]),450)}}
function improvePraise(){try{const cfg=fullParentSettings();if(cfg.sound===false)return;improveChime();if(window.speechSynthesis&&window.SpeechSynthesisUtterance){window.speechSynthesis.cancel();let u=new SpeechSynthesisUtterance('Yay! Great job!');u.lang='en-US';u.rate=.92;u.pitch=1.38;u.volume=1;window.speechSynthesis.speak(u);return}}catch(e){}}
function improveChime(){try{let C=window.AudioContext||window.webkitAudioContext;if(!C)return;let c=new C(),notes=[523,659,784];notes.forEach((freq,i)=>{let o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,c.currentTime+i*.13);g.gain.exponentialRampToValueAtTime(.13,c.currentTime+i*.13+.02);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+i*.13+.23);o.connect(g);g.connect(c.destination);o.start(c.currentTime+i*.13);o.stop(c.currentTime+i*.13+.25)})}catch(e){}}
function rizqiLoad(){try{return JSON.parse(localStorage.getItem(RIZQI_PROGRESS)||'{}')}catch(e){return {}}}
function rizqiSave(){try{const all=rizqiLoad();all[fullRizqi.kind]={level:fullRizqi.level,idx:fullRizqi.idx};localStorage.setItem(RIZQI_PROGRESS,JSON.stringify(all))}catch(e){}}
const oldRizqiNew=fullNewRizqi;
fullNewRizqi=function(kind){let old=oldRizqiNew(kind),saved=rizqiLoad()[kind]||{};return {...old,level:Math.min(3,Math.max(1,Number(saved.level)||1)),idx:Math.min(9,Math.max(0,Number(saved.idx)||0)),pairs:(kind==='safari'||kind==='picture')?SAFARI_ANIMALS.map(x=>[x,x.toLowerCase()]):kind==='shapes'?SHAPE_TYPES.map(x=>[x,x]):old.pairs}}
function rizqiKindImage(kind,name){if(kind==='safari'||kind==='picture')return gameImage(name.toLowerCase(),name,'rizqi-animal-image');if(kind==='shapes')return shapeSvg(name);return `<span class="full-color-blob" style="background:${qSafe(name)}"></span>`}
fullRizqiView=function(m){const kind=state.detail;if(!fullRizqi||fullRizqi.kind!==kind)fullRizqi=fullNewRizqi(kind);const g=fullRizqi,pair=g.pairs[g.idx%g.pairs.length],name=pair[0];const title=MODULES.rizqi.items.find(x=>x.id===kind)?.name||'Rizqi Explorer';let html='';
 if(kind==='shapes'){
 const target=SHAPE_TYPES[g.idx%SHAPE_TYPES.length];const choices=shuffled(SHAPE_TYPES.slice());html=`<div class="rizqi-title">Drag the shape to its matching home!</div><div class="shape-drop-board"><div class="shape-drop-slot" data-shape-drop="${target}" aria-label="Drop the ${target} shape here">${shapeSvg(target)}<span>${target}</span></div></div><div class="shape-palette">${choices.map(x=>`<button class="shape-draggable" data-shape-pick="${x}" draggable="true" aria-label="Drag ${x}">${shapeSvg(x)}<small>${x}</small></button>`).join('')}</div><p class="game-search-tip">Drag and drop • or tap a shape, then tap the board</p>`;
 }else if(kind==='safari'){
 const names=shuffled(SAFARI_ANIMALS.filter(x=>x!==name)).slice(0,g.level);names.push(name);html=`<div class="rizqi-title">What animal is this?</div><div class="safari-picture">${gameImage(name.toLowerCase(),name,'rizqi-animal-image')}</div><div class="rizqi-name-choices">${shuffled(names).map(x=>`<button type="button" data-improve-rizqi="${x}">${qSafe(x)}</button>`).join('')}</div>`;
 }else{
 let visual=kind==='rainbow'?`<span class="full-color-blob" style="background:${pair[1]}"></span>`:gameImage(String(pair[1]).toLowerCase(),name,'rizqi-animal-image');let choices=shuffled(g.pairs.filter(x=>x[0]!==name)).slice(0,g.level);choices.push(pair);html=`<div class="rizqi-title">${kind==='rainbow'?'Choose the matching colour!':'Find the same picture!'}</div><div class="full-rizqi-object rizqi-3d-object">${visual}</div><div class="full-rizqi-choices ${kind==='picture'?'picture-choice-grid':''}">${shuffled(choices).map(x=>kind==='picture'?`<button type="button" class="picture-choice-btn" data-improve-rizqi="${qSafe(x[0])}" aria-label="Select ${qSafe(x[0])}">${gameImage(String(x[1]).toLowerCase(),x[0],'rizqi-choice-image')}</button>`:`<button data-improve-rizqi="${qSafe(x[0])}">${qSafe(x[0])}</button>`).join('')}</div>`;
 }
 return `<section class="panel app-screen module-shell improved-module">${head(m)}<div class="game-hero rizqi-theme"><span class="game-kicker">RIZQI EXPLORER</span><h2>${qSafe(title)}</h2><p>Level ${g.level} · ${g.idx+1} of 10</p><button type="button" class="sound-test" data-rizqi-voice>🔊 Test happy voice</button></div><div class="full-rizqi-game rizqi-play-area">${html}<p id="rizqiFeedback" role="status" class="game-feedback"></p></div></section>`;
};
function rizqiCorrect(){let g=fullRizqi;if(!g)return;let el=document.getElementById('rizqiFeedback');if(el){el.textContent='Yay! Great job!';el.classList.add('is-good')}improvePraise();g.idx++;g.errors=0;if(g.idx>=10){g.idx=0;g.level=Math.min(3,g.level+1)}rizqiSave();setTimeout(()=>{if(state.view==='rizqi'&&state.detail===g.kind)render()},900)}
function rizqiWrong(){let g=fullRizqi;if(!g)return;g.errors++;let current=g.kind==='shapes'?SHAPE_TYPES[g.idx%5]:g.pairs[g.idx%g.pairs.length][0];let el=document.getElementById('rizqiFeedback');if(el)el.textContent=g.errors>=2?`Hint: find ${current}!`:'Try again, little explorer!';if(g.errors>=2){let btn=document.querySelector(`[data-improve-rizqi="${current}"], [data-shape-pick="${current}"]`);btn?.classList.add('hint-glow')}}
// Custom events have distinct data attributes so legacy event listeners remain untouched.
document.getElementById('view').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-game-letter')){const i=Number(b.dataset.gameLetter),g=fullGame;if(!g||g.kind!=='word'||b.disabled)return;gameTileBuffer.push({i,letter:g.letters[i]});b.disabled=true;const slots=document.querySelector('.game-letter-slots');if(slots)slots.innerHTML=g.word.split('').map((_,j)=>`<span class="letter-slot">${gameTileBuffer[j]?.letter||'·'}</span>`).join('');if(gameTileBuffer.length===g.word.length){let s=gameTileBuffer.map(x=>x.letter).join('');if(s===g.word)gameSolved();else improveFeedback('Not quite! Tap Clear and try again.')}return}
 if(b.hasAttribute('data-game-reset')){gameTileBuffer=[];render();return}
 if(b.hasAttribute('data-game-new')){let score=fullGame?.score||0;fullGame=fullNewGame(state.detail);fullGame.score=score;gameTileBuffer=[];render();return}
 if(b.hasAttribute('data-improve-hint')){improveFeedback(`Hint: ${fullGame.word.charAt(0)} _ _ ... (${fullGame.word.length} letters)`);return}
 if(b.hasAttribute('data-improve-check')){if(fullGame.kind==='math')gameMathCheck();else gameSpellingCheck();return}
 if(b.hasAttribute('data-rizqi-voice')){improvePraise();return}
 if(b.hasAttribute('data-improve-rizqi')){const g=fullRizqi,correct=g.pairs[g.idx%g.pairs.length][0];b.dataset.improveRizqi===correct?rizqiCorrect():rizqiWrong();return}
 if(b.hasAttribute('data-shape-pick')){document.querySelectorAll('[data-shape-pick]').forEach(el=>el.classList.remove('picked'));b.classList.add('picked');shapeDrag=b.dataset.shapePick;return}
});
const appView=document.getElementById('view');
appView.addEventListener('pointerdown',e=>{let cell=e.target.closest('[data-search-cell]');if(!cell||!fullGame||fullGame.kind!=='search')return;e.preventDefault();let el=cell.closest('.game-search-board');if(!el)return;gamePointer={id:e.pointerId,start:Number(cell.dataset.searchCell),el};el.setPointerCapture(e.pointerId);gridPaint([gamePointer.start])});
appView.addEventListener('pointermove',e=>{if(!gamePointer||e.pointerId!==gamePointer.id)return;let hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-search-cell]');if(!hit)return;let path=gridLine(gamePointer.start,Number(hit.dataset.searchCell),fullGame.size);gridPaint(path)});
appView.addEventListener('pointerup',e=>{if(!gamePointer||e.pointerId!==gamePointer.id)return;let hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-search-cell]');let end=hit?Number(hit.dataset.searchCell):gamePointer.start;let path=gridLine(gamePointer.start,end,fullGame.size);gamePointer=null;gridFinish(path)});
appView.addEventListener('pointercancel',()=>{gamePointer=null;gridPaint([])});
appView.addEventListener('dragstart',e=>{let b=e.target.closest('[data-shape-pick]');if(!b)return;shapeDrag=b.dataset.shapePick;e.dataTransfer?.setData('text/plain',shapeDrag)});
appView.addEventListener('dragover',e=>{if(e.target.closest('[data-shape-drop]'))e.preventDefault()});
appView.addEventListener('drop',e=>{const slot=e.target.closest('[data-shape-drop]');if(!slot)return;e.preventDefault();const pick=e.dataTransfer?.getData('text/plain')||shapeDrag;pick===slot.dataset.shapeDrop?rizqiCorrect():rizqiWrong();shapeDrag=null});
appView.addEventListener('click',e=>{let slot=e.target.closest('[data-shape-drop]');if(slot&&shapeDrag){shapeDrag===slot.dataset.shapeDrop?rizqiCorrect():rizqiWrong();shapeDrag=null}});
// Touch-friendly drag/drop for Safari iOS (native HTML drag often unavailable).
appView.addEventListener('pointerdown',e=>{let s=e.target.closest('[data-shape-pick]');if(!s)return;shapeDrag=s.dataset.shapePick;s.dataset.dragging='true'});
appView.addEventListener('pointerup',e=>{let selected=document.querySelector('[data-shape-pick][data-dragging]');if(!selected)return;delete selected.dataset.dragging;let slot=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-shape-drop]');if(slot){shapeDrag===slot.dataset.shapeDrop?rizqiCorrect():rizqiWrong();shapeDrag=null}});
